public with sharing class RecordSearchService {
    public class SearchException extends Exception {}

    private static Map<String, Schema.SObjectType> globalTypeCache;
    private static Map<String, Schema.DescribeSObjectResult> objDescribeCache = new Map<String, Schema.DescribeSObjectResult>();
    private static Map<String, Map<String, Schema.SObjectField>> fieldMapCache = new Map<String, Map<String, Schema.SObjectField>>();

    private static void initGlobalCache() {
        if (globalTypeCache != null) return;
        globalTypeCache = new Map<String, Schema.SObjectType>();
        for (String name : Schema.getGlobalDescribe().keySet()) {
            globalTypeCache.put(name.toLowerCase(), Schema.getGlobalDescribe().get(name));
        }
    }

    private static Schema.DescribeSObjectResult getDescribe(Schema.SObjectType sType) {
        String key = sType.getDescribe().getName().toLowerCase();
        if (!objDescribeCache.containsKey(key)) {
            objDescribeCache.put(key, sType.getDescribe());
        }
        return objDescribeCache.get(key);
    }

    private static Map<String, Schema.SObjectField> getFieldMapLower(Schema.DescribeSObjectResult describe) {
        String key = describe.getName().toLowerCase();
        if (fieldMapCache.containsKey(key)) {
            return fieldMapCache.get(key);
        }
        Map<String, Schema.SObjectField> mapLower = new Map<String, Schema.SObjectField>();
        for (String fName : describe.fields.getMap().keySet()) {
            mapLower.put(fName.toLowerCase(), describe.fields.getMap().get(fName));
        }
        fieldMapCache.put(key, mapLower);
        return mapLower;
    }

    public static List<SObject> search(String objectApiName, List<String> fields, Map<String, Object> filters, String orderByField, Integer maxRows) {
        try {
            if (String.isBlank(objectApiName)) {
                throw new SearchException('Object API name is required');
            }
            if (fields == null || fields.isEmpty()) {
                throw new SearchException('Fields list is required');
            }
            if (maxRows == null || maxRows < 1 || maxRows > 200) {
                throw new SearchException('maxRows must be between 1 and 200');
            }

            initGlobalCache();
            Schema.SObjectType sObjType = globalTypeCache.get(objectApiName.trim().toLowerCase());
            if (sObjType == null) {
                throw new SearchException('Object does not exist: ' + objectApiName);
            }
            Schema.DescribeSObjectResult objDescribe = getDescribe(sObjType);
            if (!objDescribe.isAccessible() || !objDescribe.isQueryable()) {
                throw new SearchException('Object not accessible or not queryable: ' + objectApiName);
            }
            String objectName = objDescribe.getName();

            Map<String, Schema.SObjectField> fieldMapLower = getFieldMapLower(objDescribe);

            List<String> selectFields = new List<String>();
            Set<String> seenLower = new Set<String>();
            for (String f : fields) {
                if (String.isBlank(f)) {
                    throw new SearchException('Blank field name in fields list');
                }
                String fLower = f.trim().toLowerCase();
                Schema.SObjectField sField = fieldMapLower.get(fLower);
                if (sField == null) {
                    throw new SearchException('Field does not exist: ' + f);
                }
                Schema.DescribeFieldResult fDescribe = sField.getDescribe();
                if (!fDescribe.isAccessible()) {
                    throw new SearchException('Field not accessible: ' + f);
                }
                String actualName = fDescribe.getName();
                String actualLower = actualName.toLowerCase();
                if (actualLower != 'id' && !seenLower.contains(actualLower)) {
                    seenLower.add(actualLower);
                    selectFields.add(actualName);
                }
            }

            String orderByActual = null;
            if (!String.isBlank(orderByField)) {
                String obLower = orderByField.trim().toLowerCase();
                Schema.SObjectField sField = fieldMapLower.get(obLower);
                if (sField == null) {
                    throw new SearchException('Order by field does not exist: ' + orderByField);
                }
                Schema.DescribeFieldResult fDescribe = sField.getDescribe();
                if (!fDescribe.isAccessible()) {
                    throw new SearchException('Order by field not accessible: ' + orderByField);
                }
                if (!fDescribe.isSortable()) {
                    throw new SearchException('Order by field cannot be sorted: ' + orderByField);
                }
                orderByActual = fDescribe.getName();
            }

            Map<String, Object> validatedFilters = new Map<String, Object>();
            if (filters != null && !filters.isEmpty()) {
                for (String fKey : filters.keySet()) {
                    if (String.isBlank(fKey)) {
                        throw new SearchException('Blank filter field name');
                    }
                    String fLower = fKey.trim().toLowerCase();
                    Schema.SObjectField sField = fieldMapLower.get(fLower);
                    if (sField == null) {
                        throw new SearchException('Filter field does not exist: ' + fKey);
                    }
                    Schema.DescribeFieldResult fDescribe = sField.getDescribe();
                    if (!fDescribe.isAccessible()) {
                        throw new SearchException('Filter field not accessible: ' + fKey);
                    }
                    if (!fDescribe.isFilterable()) {
                        throw new SearchException('Filter field cannot be filtered: ' + fKey);
                    }
                    validatedFilters.put(fDescribe.getName(), filters.get(fKey));
                }
            }

            String query = 'SELECT Id';
            for (String f : selectFields) {
                query += ', ' + f;
            }
            query += ' FROM ' + objectName;

            if (!validatedFilters.isEmpty()) {
                List<String> conditions = new List<String>();
                for (String fieldName : validatedFilters.keySet()) {
                    Object val = validatedFilters.get(fieldName);
                    if (val == null) {
                        conditions.add(fieldName + ' IS NULL');
                    } else {
                        conditions.add(fieldName + ' = ' + formatValueForSOQL(val));
                    }
                }
                query += ' WHERE ' + String.join(conditions, ' AND ');
            }

            if (orderByActual != null) {
                query += ' ORDER BY ' + orderByActual + ' ASC';
            }
            query += ' LIMIT ' + maxRows;

            return Database.query(query);
        } catch (SearchException se) {
            throw se;
        } catch (Exception e) {
            throw new SearchException(e.getMessage());
        }
    }

    private static String formatValueForSOQL(Object val) {
        if (val instanceof String) {
            return '\'' + String.valueOf(val).replace('\'', '\'\'') + '\'';
        }
        if (val instanceof Id) {
            return '\'' + String.valueOf(val).replace('\'', '\'\'') + '\'';
        }
        if (val instanceof Boolean) {
            return String.valueOf(val);
        }
        if (val instanceof Integer) {
            return String.valueOf(val);
        }
        if (val instanceof Long) {
            return String.valueOf(val);
        }
        if (val instanceof Decimal) {
            return String.valueOf(val);
        }
        if (val instanceof Date) {
            return String.valueOf(val);
        }
        if (val instanceof Datetime) {
            Datetime dt = (Datetime)val;
            return '\'' + dt.formatGmt('yyyy-MM-dd HH:mm:ss') + '\'';
        }
        return '\'' + String.valueOf(val).replace('\'', '\'\'') + '\'';
    }
}
