public class Opportunities extends fflib_SObjectDomain {

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjects) {
            return new Opportunities(sObjects);
        }
    }

    public Opportunities(List<SObject> records) {
        super(records);
    }

    public override void onAfterInsert() {
        Set<Id> qualifyingIds = new Set<Id>();
        for (Opportunity opp : (List<Opportunity>) getRecords()) {
            if (opp.StageName == 'Closed Won') {
                qualifyingIds.add(opp.Id);
            }
        }
        if (!qualifyingIds.isEmpty()) {
            IOpportunityFulfilmentService service = (IOpportunityFulfilmentService) Application.Service.newInstance(IOpportunityFulfilmentService.class);
            service.startFulfilment(qualifyingIds);
        }
    }

    public override void onAfterUpdate(Map<Id, SObject> oldRecordsMap) {
        Set<Id> qualifyingIds = new Set<Id>();
        for (Opportunity opp : (List<Opportunity>) getRecords()) {
            Opportunity oldOpp = (Opportunity) oldRecordsMap.get(opp.Id);
            if (opp.StageName == 'Closed Won' && oldOpp != null && oldOpp.StageName != 'Closed Won') {
                qualifyingIds.add(opp.Id);
            }
        }
        if (!qualifyingIds.isEmpty()) {
            IOpportunityFulfilmentService service = (IOpportunityFulfilmentService) Application.Service.newInstance(IOpportunityFulfilmentService.class);
            service.startFulfilment(qualifyingIds);
        }
    }
}
