    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Opportunity>();
        }

        fflib_QueryFactory qf = newQueryFactory();
        qf.selectFields(getSObjectFieldList());
        qf.selectField('Account.Name');
        qf.setCondition('IsClosed = false AND AccountId IN :accountIds');

        // Amount NULLS LAST, then Amount DESC, then CloseDate ASC
        // fflib_QueryFactory.orderBy(field, isAsc) where isAsc = true for ASC
        qf.orderBy('CASE WHEN Amount IS NULL THEN 1 ELSE 0 END', true);
        qf.orderBy('Amount', false);
        qf.orderBy('CloseDate', true);

        if (maxRecords != null && maxRecords > 0) {
            qf.setLimit(maxRecords);
        }

        return (List<Opportunity>) Database.query(qf.toSOQL());
    }
}
