public with sharing class ContactEmailMatcher {

    public class Request {
        @InvocableVariable(required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable
        public Id contactId;
    }

    @InvocableMethod(label='Match Contact by Email')
    public static List<Result> match(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null) {
            return results;
        }

        Map<Integer, String> idxToNorm = new Map<Integer, String>();
        Set<String> distinctNormEmails = new Set<String>();

        for (Integer i = 0; i < requests.size(); i++) {
            String raw = requests[i] != null ? requests[i].email : null;
            if (String.isBlank(raw)) {
                idxToNorm.put(i, null);
                continue;
            }
            String norm = raw.trim().toLowerCase();
            idxToNorm.put(i, norm);
            distinctNormEmails.add(norm);
        }

        Map<String, Contact> bestByEmail = new Map<String, Contact>();
        if (!distinctNormEmails.isEmpty()) {
            List<Contact> contacts = [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE Email IN :distinctNormEmails
            ];
            for (Contact c : contacts) {
                if (c.Email == null) continue;
                String norm = c.Email.trim().toLowerCase();
                if (!bestByEmail.containsKey(norm)) {
                    bestByEmail.put(norm, c);
                } else {
                    Contact existing = bestByEmail.get(norm);
                    if (c.CreatedDate < existing.CreatedDate ||
                        (c.CreatedDate == existing.CreatedDate && c.Id < existing.Id)) {
                        bestByEmail.put(norm, c);
                    }
                }
            }
        }

        for (Integer i = 0; i < requests.size(); i++) {
            Result r = new Result();
            String norm = idxToNorm.get(i);
            if (String.isBlank(norm)) {
                r.contactId = null;
            } else {
                Contact best = bestByEmail.get(norm);
                r.contactId = best != null ? best.Id : null;
            }
            results.add(r);
        }
        return results;
    }
}
