public class ErpCustomerSync {
    private static final Integer CALL_OUT_LIMIT = 100;

    public static void enqueueForAccounts(List<Account> accounts) {
        if (accounts == null || accounts.isEmpty()) {
            return;
        }
        System.enqueueJob(new SyncJob(accounts));
    }

    public static class SyncJob implements Queueable, Database.AllowsCallouts {
        private List<Account> accounts;

        public SyncJob(List<Account> accounts) {
            this.accounts = accounts;
        }

        public void execute(QueueableContext ctx) {
            if (accounts == null || accounts.isEmpty()) {
                return;
            }

            if (accounts.size() > CALL_OUT_LIMIT) {
                List<Account> firstBatch = new List<Account>();
                for (Integer i = 0; i < CALL_OUT_LIMIT; i++) {
                    firstBatch.add(accounts[i]);
                }
                List<Account> remaining = new List<Account>();
                for (Integer i = CALL_OUT_LIMIT; i < accounts.size(); i++) {
                    remaining.add(accounts[i]);
                }
                processBatch(firstBatch);
                System.enqueueJob(new SyncJob(remaining));
            } else {
                processBatch(accounts);
            }
        }

        private void processBatch(List<Account> batch) {
            Http http = new Http();
            for (Account a : batch) {
                HttpRequest req = new HttpRequest();
                req.setEndpoint('callout:ERP/api/customers');
                req.setMethod('POST');
                req.setHeader('Content-Type', 'application/json');

                String salesforceId = String.valueOf(a.Id);
                String name = a.Name;
                String country = String.isBlank(a.BillingCountry) ? null : a.BillingCountry;

                Map<String, Object> item = new Map<String, Object>{
                    'salesforceId' => salesforceId,
                    'name'         => name,
                    'country'      => country
                };
                String body = JSON.serialize(new List<Object>{ item });
                req.setBody(body);

                http.send(req);
            }
        }
    }
}
