public class RenewalReminderService {

    /*
     * The original request to call Messaging.sendEmail once per opportunity inside a loop
     * is a bad idea. Each Messaging.sendEmail invocation counts against the per-transaction
     * Email Invocations limit of 10 and adds CPU overhead. With up to 200 opportunities
     * this throws System.LimitException: Too many Email Invocations and exceeds the
     * 100 emails per transaction limit. The correct bulk pattern is to build all
     * SingleEmailMessage instances and send them in batches of <=100, then inspect the
     * SendEmailResult[] for individual failures.
     */

    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        Set<Id> idSet = new Set<Id>(opportunityIds);
        List<Opportunity> opps = [
            SELECT Id, Name, CloseDate, OwnerId
            FROM Opportunity
            WHERE Id IN :idSet
        ];

        List<Messaging.SingleEmailMessage> mails = new List<Messaging.SingleEmailMessage>();

        for (Opportunity opp : opps) {
            if (opp.OwnerId == null) {
                continue;
            }
            // Only Users can be targeted directly with setTargetObjectId
            if (!String.valueOf(opp.OwnerId).startsWith('005')) {
                continue;
            }

            Messaging.SingleEmailMessage mail = new Messaging.SingleEmailMessage();
            mail.setTargetObjectId(opp.OwnerId);
            mail.setTreatTargetObjectAsRecipient(true);
            mail.setSaveAsActivity(false);
            mail.setSubject('Renewal due: ' + opp.Name);

            String closeDateText = opp.CloseDate != null ? String.valueOf(opp.CloseDate) : 'unknown date';
            String body = 'Hello,\n\n'
                + 'The opportunity "' + opp.Name + '" has a renewal due on ' + closeDateText + '.\n'
                + 'Please review the record and take the required action.\n\n'
                + 'Thanks';
            mail.setPlainTextBody(body);

            mails.add(mail);
        }

        if (mails.isEmpty()) {
            return 0;
        }

        Integer sentCount = 0;
        List<Messaging.SingleEmailMessage> batch = new List<Messaging.SingleEmailMessage>();

        for (Messaging.SingleEmailMessage m : mails) {
            batch.add(m);
            if (batch.size() == 100) {
                Messaging.SendEmailResult[] results = Messaging.sendEmail(batch);
                if (results != null) {
                    for (Messaging.SendEmailResult res : results) {
                        if (res.isSuccess()) {
                            sentCount++;
                        }
                    }
                }
                batch.clear();
            }
        }

        if (!batch.isEmpty()) {
            Messaging.SendEmailResult[] results = Messaging.sendEmail(batch);
            if (results != null) {
                for (Messaging.SendEmailResult res : results) {
                    if (res.isSuccess()) {
                        sentCount++;
                    }
                }
            }
        }

        return sentCount;
    }
}
