import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
  @api label;

  _options = [];
  _value;
  _activeValue;

  @api
  get options() {
    return this._options;
  }
  set options(val) {
    this._options = Array.isArray(val) ? val : [];
    this._syncState();
  }

  @api
  get value() {
    return this._value;
  }
  set value(val) {
    this._value = val;
    this._syncState();
  }

  connectedCallback() {
    this._syncState();
  }

  _syncState() {
    const opts = this._options;
    if (!opts || opts.length === 0) {
      this._activeValue = undefined;
      return;
    }
    const hasValidValue = this._value != null && this._value !== '' && opts.some(o => o.value === this._value);
    if (hasValidValue) {
      this._activeValue = this._value;
    } else {
      this._activeValue = opts[0].value;
    }
  }

  get listOptions() {
    return this._options.map((o, i) => ({
      value: o.value,
      label: o.label,
      id: 'option-' + i,
      isSelected: o.value === this._value
    }));
  }

  get activeIndex() {
    if (this._activeValue == null) return -1;
    return this._options.findIndex(o => o.value === this._activeValue);
  }

  get activeId() {
    const idx = this.activeIndex;
    return idx >= 0 ? 'option-' + idx : undefined;
  }

  handleKeydown(event) {
    const key = event.key;
    const isHandled = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '].includes(key);
    if (!isHandled) {
      return;
    }
    event.preventDefault();

    const opts = this._options;
    if (!opts || opts.length === 0) return;

    let idx = this.activeIndex;
    if (idx < 0) idx = 0;

    switch (key) {
      case 'ArrowDown':
        idx = Math.min(idx + 1, opts.length - 1);
        this._activeValue = opts[idx].value;
        break;
      case 'ArrowUp':
        idx = Math.max(idx - 1, 0);
        this._activeValue = opts[idx].value;
        break;
      case 'Home':
        this._activeValue = opts[0].value;
        break;
      case 'End':
        this._activeValue = opts[opts.length - 1].value;
        break;
      case 'Enter':
      case ' ':
        const newValue = this._activeValue;
        if (newValue !== this._value) {
          this._value = newValue;
          this.dispatchEvent(new CustomEvent('change', { detail: { value: newValue } }));
        }
        break;
    }
  }

  handleClick(event) {
    const value = event.currentTarget.dataset.value;
    if (value === this._value) return;
    this._value = value;
    this._activeValue = value;
    this.dispatchEvent(new CustomEvent('change', { detail: { value } }));
  }
}
