public class HouseholdService {

    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must not be null or empty');
        }

        RecordType householdRT;
        try {
            householdRT = [
                SELECT Id
                FROM RecordType
                WHERE SObjectType = 'Account' AND DeveloperName = 'HH_Account'
                LIMIT 1
            ];
        } catch (Exception e) {
            throw new IllegalArgumentException('Household Account record type HH_Account not found');
        }

        Savepoint sp = Database.setSavepoint();
        try {
            // Insert the primary contact first so we have an Id to link to the household.
            Contact primary = members[0];
            primary.AccountId = null;
            insert primary;

            // Create the household with the primary contact set before insert so NPSP
            // can name the account from the contact on insert. Name is intentionally
            // left unset so NPSP generates it and the greeting.
            Account household = new Account(
                RecordTypeId = householdRT.Id,
                npe01__One2OneContact__c = primary.Id
            );
            insert household;

            // Link the primary contact to the household
            primary.AccountId = household.Id;
            update primary;

            // Insert the remaining members linked to the same household
            if (members.size() > 1) {
                List<Contact> rest = members.subList(1, members.size());
                for (Contact c : rest) {
                    c.AccountId = household.Id;
                }
                insert rest;
            }

            return household.Id;
        } catch (Exception e) {
            Database.rollback(sp);
            throw e;
        }
    }
}
