public class TA_Case_RollupOpenCount implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate, TriggerAction.AfterDelete, TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        process(triggerNew, null);
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        process(triggerNew, triggerOld);
    }

    public void afterDelete(List<SObject> triggerOld) {
        process(null, triggerOld);
    }

    public void afterUndelete(List<SObject> triggerNew) {
        process(triggerNew, null);
    }

    private void process(List<SObject> newList, List<SObject> oldList) {
        Set<Id> accountIds = new Set<Id>();

        if (newList != null) {
            for (SObject sobj : newList) {
                Case c = (Case)sobj;
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
            }
        }
        if (oldList != null) {
            for (SObject sobj : oldList) {
                Case c = (Case)sobj;
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Integer> countMap = new Map<Id, Integer>();
        for (AggregateResult ar : [
            SELECT AccountId, COUNT(Id) cnt
            FROM Case
            WHERE AccountId IN :accountIds AND IsClosed = FALSE
            GROUP BY AccountId
        ]) {
            Id accId = (Id)ar.get('AccountId');
            Integer cnt = (Integer)ar.get('cnt');
            countMap.put(accId, cnt);
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accId : accountIds) {
            Integer cnt = countMap.get(accId);
            if (cnt == null) {
                cnt = 0;
            }
            accountsToUpdate.add(new Account(Id = accId, FB_Open_Case_Count__c = cnt));
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
