public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        List<Task> tasksToInsert = new List<Task>();
        Map<Id, Integer> seenMap = TriggerBase.idToNumberOfTimesSeenAfterUpdate;

        for (Integer i = 0; i < triggerNew.size(); i++) {
            Opportunity newOpp = triggerNew[i];
            Opportunity oldOpp = triggerOld[i];
            Id oppId = newOpp.Id;

            Integer timesSeen = seenMap != null ? seenMap.get(oppId) : null;
            Boolean isFirstSight = timesSeen == null || timesSeen == 0;

            Boolean amountChanged = false;
            if (newOpp.Amount == null && oldOpp.Amount == null) {
                amountChanged = false;
            } else if (newOpp.Amount == null || oldOpp.Amount == null) {
                amountChanged = true;
            } else {
                amountChanged = newOpp.Amount != oldOpp.Amount;
            }

            if (isFirstSight && amountChanged) {
                tasksToInsert.add(new Task(
                    Subject = 'Amount changed',
                    WhatId = oppId,
                    Status = 'Completed'
                ));
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
