public with sharing class TA_Contact_InheritMailingAddress implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accMap = TA_Contact_Queries.getInstance().accountsById;
        for (SObject sobj : triggerNew) {
            Contact c = (Contact) sobj;
            if (c.AccountId != null && accMap.containsKey(c.AccountId)) {
                Account acc = accMap.get(c.AccountId);
                Boolean allBlank = String.isBlank(c.MailingStreet)
                    && String.isBlank(c.MailingCity)
                    && String.isBlank(c.MailingPostalCode)
                    && String.isBlank(c.MailingCountry);
                if (allBlank) {
                    if (acc.BillingStreet != null) c.MailingStreet = acc.BillingStreet;
                    if (acc.BillingCity != null) c.MailingCity = acc.BillingCity;
                    if (acc.BillingPostalCode != null) c.MailingPostalCode = acc.BillingPostalCode;
                    if (acc.BillingCountry != null) c.MailingCountry = acc.BillingCountry;
                }
            }
        }
    }
}
